package com.chesspulseai.service; import com.chesspulseai.enumtype.GamePhase; import org.junit.jupiter.api.*; import static org.junit.jupiter.api.Assertions.*; class GamePhaseDetectorTest {private final GamePhaseDetector detector=new GamePhaseDetector();@Test void classifiesStartingPositionAsOpening(){assertEquals(GamePhase.OPENING,detector.detect("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"));}@Test void detectsSparseQueenlessEndgame(){assertEquals(GamePhase.ENDGAME,detector.detect("8/8/4k3/8/8/4K3/4P3/8 w - - 0 1"));}}
